# Command-line classifier for the Bash calls of the workers (imported by measure.py).
#
# A command line is cut into statements (on ; && || | & and newlines, outside quotes), heredoc
# bodies that feed a file or an interpreter are dropped, and each statement's command word is
# found after wrappers (nohup, time, timeout, env assignments, cd ... &&, bash -c '...' which is
# classified recursively).  A statement is an "invocation" of one of these kinds:
#   ('fortress', sub)   bin/fortress <sub> ; sub in compile run walk link typecheck junit file other
#   ('harness-one',)    harness-one.sh
#   ('junit.sh',)       junit.sh
#   ('ant', target)     ant <targets>
#   ('stage', name)     checker-count/run.sh distance/run.sh mg-run.sh microgpt-phase.sh ladder
#   ('java', mainclass) a direct java -cp ... com.sun.fortress.* (a fresh JVM as well)
#   ('wait_for', log)   the skill's wait_for helper
# Anything else gives no invocation.
import re, shlex, os

WRAPPERS = {'nohup', 'time', 'timeout', 'env', 'exec', 'nice', 'setsid', 'sudo', 'command', 'stdbuf',
            'ionice', 'builtin', '!', 'then', 'do', 'else', 'elif', 'if', 'while', 'until', '{', '(', 'xargs'}
STAGE_PAT = [
    (re.compile(r'checker-count/run\.sh$'), 'checker-count'),
    (re.compile(r'distance/run\.sh$'), 'distance'),
    (re.compile(r'mg-run\.sh$'), 'mg-run'),
    (re.compile(r'microgpt-phase\.sh$'), 'microgpt-phase'),
    (re.compile(r'(^|/)(run-)?ladder[\w.-]*\.sh$'), 'ladder'),
    (re.compile(r'(^|/)ladder[\w.-]*$'), 'ladder'),
]
FSUBS = {'compile', 'run', 'walk', 'link', 'typecheck', 'junit', 'test', 'help', 'api', 'parse', 'unparse',
         'desugar', 'disambiguate', 'grammar', 'expand', 'dump', 'clean', 'tfs', 'tfi', 'rest', 'type-check'}

HEREDOC = re.compile(r"<<-?\s*(['\"]?)([A-Za-z_][\w]*)\1")


def strip_heredocs(cmd):
    """Return (text without heredoc bodies, [bodies fed to a shell]).  A body is kept as a nested
    script only when the line that opens it runs bash/sh."""
    out = []
    shell_bodies = []
    lines = cmd.split('\n')
    i = 0
    while i < len(lines):
        ln = lines[i]
        out.append(ln)
        ms = list(HEREDOC.finditer(ln))
        i += 1
        for m in ms:
            term = m.group(2)
            body = []
            while i < len(lines) and lines[i].strip() != term:
                body.append(lines[i])
                i += 1
            i += 1  # terminator
            head = ln[:m.start()]
            if re.search(r'(^|[\s;&|(])(ba)?sh(\s+-\w+)*\s*(-s)?\s*(-\s*)?$', head.strip()) or \
               re.search(r'\bbash\s*(-\w+\s*)*$', head.strip()):
                shell_bodies.append('\n'.join(body))
    return '\n'.join(out), shell_bodies


def split_statements(text):
    """Split on unquoted ; && || | & newline.  Returns list of strings.  Keeps quotes intact."""
    stmts = []
    cur = []
    i = 0
    n = len(text)
    q = None
    depth = 0
    while i < n:
        ch = text[i]
        if q:
            cur.append(ch)
            if ch == '\\' and q == '"' and i + 1 < n:
                cur.append(text[i + 1])
                i += 1
            elif ch == q:
                q = None
            i += 1
            continue
        if ch == '\\' and i + 1 < n:
            cur.append(ch)
            cur.append(text[i + 1])
            i += 2
            continue
        if ch in ('"', "'"):
            q = ch
            cur.append(ch)
            i += 1
            continue
        if ch == '#' and (not cur or cur[-1] in ' \t\n'):
            # comment to end of line
            while i < n and text[i] != '\n':
                i += 1
            continue
        if ch == '$' and i + 1 < n and text[i + 1] == '(':
            # command substitution: keep whole, classified separately by caller
            d = 0
            j = i + 1
            while j < n:
                if text[j] == '(':
                    d += 1
                elif text[j] == ')':
                    d -= 1
                    if d == 0:
                        break
                j += 1
            cur.append(text[i:j + 1])
            i = j + 1
            continue
        if ch in ';\n':
            stmts.append(''.join(cur))
            cur = []
            i += 1
            continue
        if ch == '&':
            if i + 1 < n and text[i + 1] == '&':
                stmts.append(''.join(cur)); cur = []; i += 2; continue
            # redirection like 2>&1 or &> : keep
            if i > 0 and text[i - 1] in '<>' or (i + 1 < n and text[i + 1] == '>'):
                cur.append(ch); i += 1; continue
            stmts.append(''.join(cur) + ' &'); cur = []; i += 1; continue
        if ch == '|':
            stmts.append(''.join(cur)); cur = []
            i += 2 if (i + 1 < n and text[i + 1] == '|') else 1
            continue
        cur.append(ch)
        i += 1
    stmts.append(''.join(cur))
    return [s.strip() for s in stmts if s.strip()]


def toks(stmt):
    try:
        return shlex.split(stmt, posix=True, comments=False)
    except ValueError:
        return stmt.split()


def basename(w):
    return w.rsplit('/', 1)[-1]


def invocations(cmd, depth=0):
    """List of invocations in a command line (see top of file)."""
    res = []
    if depth > 4 or not cmd:
        return res
    text, shell_bodies = strip_heredocs(cmd)
    for body in shell_bodies:
        res += invocations(body, depth + 1)
    for stmt in split_statements(text):
        # command substitutions are executed wherever they sit, also inside double quotes
        for m in re.finditer(r'\$\(([^()]*)\)|`([^`]*)`', stmt):
            res += invocations(m.group(1) or m.group(2), depth + 1)
        res += stmt_invocations(stmt, depth)
    return res


def stmt_invocations(stmt, depth):
    bg = stmt.endswith(' &')
    if bg:
        stmt = stmt[:-2]
    t = toks(stmt)
    i = 0
    # skip env assignments, wrappers and their options
    while i < len(t):
        w = t[i]
        if re.match(r'^[A-Za-z_][A-Za-z0-9_]*=', w):
            i += 1
        elif basename(w) == 'time' and w.startswith('/'):
            i += 1
            while i < len(t) and t[i].startswith('-'):
                i += 2 if t[i] in ('-f', '-o', '--format', '--output') else 1
        elif w in WRAPPERS or w == '{':
            i += 1
            if w == 'timeout':
                while i < len(t) and t[i].startswith('-'):
                    i += 1
                i += 1  # duration
            elif w in ('nice', 'ionice'):
                while i < len(t) and t[i].startswith('-'):
                    i += 2 if t[i] in ('-n', '-c') else 1
        elif w in ('cd', 'export', 'unset', 'source', '.', 'set', 'mkdir', 'echo', 'printf', 'cat', 'rm',
                   'ls', 'grep', 'sed', 'awk', 'head', 'tail', 'wc', 'git', 'cp', 'mv', 'test', '[', '[[', 'sleep',
                   'true', 'false', 'wait', 'kill', 'pkill', 'ps', 'df', 'du', 'find', 'sort', 'uniq', 'tee',
                   'touch', 'chmod', 'diff', 'cmp', 'python3', 'python', 'jq', 'rg', 'readlink', 'which', 'pwd',
                   'stat', 'date', 'ln', 'tr', 'cut', 'ss', 'curl', 'tar', 'gh', 'cd;', 'return', 'local', 'trap',
                   'ulimit', 'wc', 'xxd', 'od', 'file', 'basename', 'dirname', 'comm', 'paste', 'seq', 'free',
                   'nproc', 'uname', 'lscpu', 'id', 'whoami', 'env', 'hostname', 'md5sum', 'sha256sum', 'unzip',
                   'zip', 'jar', 'javap', 'jcmd', 'jstack', 'jps', 'strings', 'less', 'more', 'nl', 'rev',
                   'ps', 'top', 'lsof', 'pgrep', 'apt-get', 'apt', 'pip', 'pip3', 'npm', 'wget'):
            break
        else:
            break
    if i >= len(t):
        return []
    w = t[i]
    rest = t[i + 1:]
    b = basename(w)
    res = []
    if b in ('bash', 'sh', 'zsh'):
        # bash -c '<script>' or bash script.sh args
        j = 0
        script = None
        while j < len(rest):
            if rest[j] == '-c' and j + 1 < len(rest):
                script = rest[j + 1]
                break
            if rest[j].startswith('-'):
                j += 1
                continue
            break
        if script is not None:
            return invocations(script, depth + 1)
        if j < len(rest):
            name = basename(rest[j])
            for pat, st in STAGE_PAT:
                if pat.search(rest[j]):
                    return [('stage', st)]
            if name == 'harness-one.sh':
                return [('harness-one',)]
            if name == 'junit.sh':
                return [('junit.sh',)]
            return [('script', name)]
        return []
    if b == 'fortress':
        sub = None
        for r in rest:
            if r.startswith('-'):
                continue
            sub = r
            break
        if sub is None:
            return [('fortress', 'none')]
        if sub in FSUBS:
            return [('fortress', sub)]
        if sub.endswith('.fss') or sub.endswith('.fsi'):
            return [('fortress', 'file')]
        return [('fortress', 'other')]
    if b == 'harness-one.sh':
        return [('harness-one',)]
    if b == 'junit.sh':
        return [('junit.sh',)]
    for pat, st in STAGE_PAT:
        if pat.search(w):
            return [('stage', st)]
    if b == 'ant':
        targets = [r for r in rest if not r.startswith('-')]
        return [('ant', ' '.join(targets) or 'default')]
    if b in ('java',):
        if any('com.sun.fortress' in r for r in rest):
            return [('java', next((r for r in rest if r.startswith('com.sun.fortress')), 'fortress-main'))]
        return []
    if b == 'wait_for':
        return [('wait_for', rest[0] if rest else '')]
    if w.startswith('./') and w.endswith('.sh') or (b.endswith('.sh') and b not in ('env.sh',)):
        return [('script', b)]
    return []


def classify(cmd):
    """-> (class letter, [invocations], mixed flag).  Class by the heaviest kind present:
    a over b over c; (d) when none."""
    inv = invocations(cmd)
    kinds = set()
    for v in inv:
        k = v[0]
        if k in ('fortress', 'harness-one', 'junit.sh', 'java'):
            kinds.add('a')
        elif k == 'ant':
            kinds.add('b')
        elif k == 'stage':
            kinds.add('c')
    return inv, kinds

