    """Return (text without heredoc bodies, [bodies fed to a shell]).  A body is kept as a nested
    script only when the line that opens it runs bash/sh."""
    out = []
    shell_bodies = []
    lines = cmd.split('\n')
    i = 0
    while i < len(lines):
        ln = lines[i]
        out.append(ln)
        ms = list(HEREDOC.finditer(ln))
        i += 1
        for m in ms:
            term = m.group(2)
            body = []
            while i < len(lines) and lines[i].strip() != term:
                body.append(lines[i])
                i += 1
            i += 1  # terminator
            head = ln[:m.start()]
            if re.search(r'(^|[\s;&|(])(ba)?sh(\s+-\w+)*\s*(-s)?\s*(-\s*)?$', head.strip()) or \
               re.search(r'\bbash\s*(-\w+\s*)*$', head.strip()):
                shell_bodies.append('\n'.join(body))
    return '\n'.join(out), shell_bodies


def split_statements(text):
    """Split on unquoted ; && || | & newline.  Returns list of strings.  Keeps quotes intact."""
    stmts = []
    cur = []
    i = 0
    n = len(text)
    q = None
    depth = 0
    while i < n:
        ch = text[i]
        if q:
            cur.append(ch)
            if ch == '\\' and q == '"' and i + 1 < n:
                cur.append(text[i + 1])
                i += 1
            elif ch == q:
                q = None
            i += 1
            continue
        if ch == '\\' and i + 1 < n:
            cur.append(ch)
            cur.append(text[i + 1])
            i += 2
            continue
        if ch in ('"', "'"):
            q = ch
            cur.append(ch)
            i += 1
            continue
        if ch == '#' and (not cur or cur[-1] in ' \t\n'):
            # comment to end of line
            while i < n and text[i] != '\n':
                i += 1
            continue
        if ch == '$' and i + 1 < n and text[i + 1] == '(':
            # command substitution: keep whole, classified separately by caller
            d = 0
            j = i + 1
            while j < n:
                if text[j] == '(':
                    d += 1
                elif text[j] == ')':
                    d -= 1
                    if d == 0:
                        break
                j += 1
            cur.append(text[i:j + 1])
            i = j + 1
            continue
        if ch in ';\n':
            stmts.append(''.join(cur))
            cur = []
            i += 1
            continue
        if ch == '&':
            if i + 1 < n and text[i + 1] == '&':
                stmts.append(''.join(cur)); cur = []; i += 2; continue
            # redirection like 2>&1 or &> : keep
            if i > 0 and text[i - 1] in '<>' or (i + 1 < n and text[i + 1] == '>'):
                cur.append(ch); i += 1; continue
            stmts.append(''.join(cur) + ' &'); cur = []; i += 1; continue
        if ch == '|':
            stmts.append(''.join(cur)); cur = []
            i += 2 if (i + 1 < n and text[i + 1] == '|') else 1
            continue
        cur.append(ch)
        i += 1
    stmts.append(''.join(cur))
    return [s.strip() for s in stmts if s.strip()]


