def basename(w):
    return w.rsplit('/', 1)[-1]


def invocations(cmd, depth=0):
    """List of invocations in a command line (see top of file)."""
    res = []
    if depth > 4 or not cmd:
        return res
    text, shell_bodies = strip_heredocs(cmd)
    for body in shell_bodies:
        res += invocations(body, depth + 1)
    for stmt in split_statements(text):
        # command substitutions are executed wherever they sit, also inside double quotes
        for m in re.finditer(r'\$\(([^()]*)\)|`([^`]*)`', stmt):
            res += invocations(m.group(1) or m.group(2), depth + 1)
        res += stmt_invocations(stmt, depth)
    return res


